export const LAKE={x:0,z:110,rx:24,rz:17,approach:{x:0,z:97}};
export function lakeBlocked(x,z){const water=((x-LAKE.x)/LAKE.rx)**2+((z-LAKE.z)/LAKE.rz)**2<1;return water&&!(Math.abs(x)<1.2&&z>=86&&z<=101);}
export function ensureFishing(s){if(!s.fishing)s.fishing={version:1,cast:null,sequence:0,catches:[]};s.inventory.fish??=0;if(!s.offers.some(o=>o.good==='fish'))s.offers.push({good:'fish',seller:'Village fish buyers',price:6,stock:0,buy:80});return s.fishing;}
export function castLine(s,position,now=Date.now()){const f=ensureFishing(s);if(f.cast)throw Error('Reel in or cancel the current cast first.');if(Math.hypot(position.x,position.z-97)>1.5)throw Error('Walk onto the fishing pier first.');if(s.inventory.maize<1)throw Error('Use 1 maize as bait.');s.inventory.maize--;const id=++f.sequence,delay=8000+(id*7381+s.day*137)%12000;f.cast={id,startedAt:now,biteAt:now+delay,expiresAt:now+delay+10000};return f.cast;}
export function fishingStatus(s,now=Date.now()){const c=s.fishing?.cast;return !c?'idle':now<c.biteAt?'waiting':now<=c.expiresAt?'bite':'missed';}
export function reelIn(s,position,now=Date.now()){const f=ensureFishing(s),status=fishingStatus(s,now);if(status==='idle')throw Error('Cast your line first.');if(Math.hypot(position.x,position.z-97)>1.8){f.cast=null;throw Error('You left the pier; the cast was cancelled.');}if(status==='waiting')throw Error('Wait until the float dips and a fish bites.');if(status==='missed'){f.cast=null;throw Error('The fish escaped. Cast again.');}const c=f.cast,fish={id:c.id,species:['Carp','Bream','Catfish'][c.id%3],weight:Math.round((.4+(c.id*37%31)/10)*10)/10,caughtAt:now};f.cast=null;f.catches.unshift(fish);f.catches=f.catches.slice(0,20);s.inventory.fish++;return fish;}
export function cancelFishing(s){if(s.fishing)s.fishing.cast=null;}
